<?php
declare(strict_types=1);
require __DIR__ . '/../lib/bootstrap.php';
require __DIR__ . '/../includes/seo.php';
$slug=trim((string)($_GET['slug']??''));$stmt=db()->prepare('SELECT * FROM categories WHERE slug=? AND active=1 LIMIT 1');$stmt->execute([$slug]);$category=$stmt->fetch();
if(!$category){http_response_code(404);$title='Categoría no encontrada | '.BUSINESS_NAME;$description='La categoría solicitada no está disponible.';$products=[];}else{$title=trim((string)($category['seo_title']??''))?:$category['name'].' en '.BUSINESS_CITY.' | '.BUSINESS_NAME;$description=trim((string)($category['seo_description']??''))?:'Consulta productos de '.$category['name'].' en '.BUSINESS_NAME.'. Despacho sujeto a coordinación en Villarrica, Licán Ray, Pucón, Coñaripe y Panguipulli.';$q=db()->prepare('SELECT p.id,p.name,p.slug,p.short_description,p.price,p.brand,(SELECT path FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_cover DESC,i.sort_order,i.id LIMIT 1) image FROM products p WHERE p.category_id=? AND p.active=1 ORDER BY p.sort_order,p.name');$q->execute([$category['id']]);$products=$q->fetchAll();}
?><!doctype html><html lang="es-CL"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php seo_head(['title'=>$title,'description'=>$description,'path'=>'/categoria/'.rawurlencode($slug).'/','noindex'=>$category&&!($category['seo_indexable']??1)]);?><link rel="stylesheet" href="../styles.css"><?php seo_jsonld(seo_business_schema());?></head><body><header class="site-header"><a class="brand" href="../index.html">Ferretería <strong>El Volcán</strong></a><nav><a href="../index.html">Inicio</a><a href="../catalogo.html">Catálogo completo</a></nav></header><main class="catalog-section"><?php if(!$category):?><h1>Categoría no encontrada</h1><?php else:?><p class="eyebrow dark">Catálogo Ferretería El Volcán</p><h1><?=seo_escape($category['name'])?> en la zona lacustre</h1><p><?=nl2br(seo_escape($category['seo_content']?:$category['description']?:'Consulta nuestra selección de '.$category['name'].'. Solicita disponibilidad y cotización por WhatsApp.'))?></p><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><?php if($p['image']):?><a href="../producto/<?=rawurlencode($p['slug'])?>/"><img src="../<?=seo_escape($p['image'])?>" alt="<?=seo_escape($p['name'])?>" loading="lazy"></a><?php endif;?><div class="product-info"><h2><a href="../producto/<?=rawurlencode($p['slug'])?>/"><?=seo_escape($p['name'])?></a></h2><p><?=seo_escape($p['short_description']??'')?></p><a href="../producto/<?=rawurlencode($p['slug'])?>/">Ver producto →</a></div></article><?php endforeach;?></div><?php endif;?></main><footer><p><?=BUSINESS_NAME?> · <?=BUSINESS_ADDRESS?></p><a href="<?=BUSINESS_MAPS?>">Cómo llegar</a></footer></body></html>
